WITH RecentCustomers AS (SELECT * FROM customers WHERE name LIKE 'O%'), Summary AS (SELECT segment, QUARTER(signup_date) AS signup_quarter, SUM(age) AS total_age, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(country))) AS country_values FROM RecentCustomers GROUP BY segment, QUARTER(signup_date)) SELECT segment, signup_quarter, total_age FROM Summary WHERE total_age > 180 ORDER BY signup_quarter DESC, total_age DESC
